document.addEventListener("DOMContentLoaded",()=>{const e=[{year:"1920",title:"Early Life",description:"Born on 25 March 1920 in Saras village near Surat, Gujarat. She was deeply influenced by Gandhi's ideals from childhood."},{year:"1928",title:"First Protest",description:"At age eight, she participated in a protest march against the Simon Commission."},{year:"August 1942",title:"Quit India Movement",description:"When the Quit India Movement was launched and leaders were arrested, Usha Mehta and her associates set up the Secret Congress Radio."},{year:"Aug - Nov 1942",title:"Underground Broadcasting",description:"The radio station broadcasted on 42.34 meters from changing locations in Bombay to avoid detection, spreading news of the freedom struggle."},{year:"November 1942",title:"Arrest",description:"The CID traced the location of the radio station, and Usha Mehta along with her associates were arrested and sentenced to imprisonment."},{year:"1946",title:"Release",description:"She was released from Yerwada Jail and went on to complete her Ph.D. on the political and social thought of Mahatma Gandhi."},{year:"1998",title:"Padma Vibhushan",description:"The Government of India conferred on her the Padma Vibhushan, the second highest civilian award."}],t=document.getElementById("timeline-container");t&&e.forEach((e,n)=>{const a=`\n                <div class="timeline-event ${n%2==0?"left":"right"}">\n                    <div class="timeline-content">\n                        <div class="timeline-year">${e.year}</div>\n                        <h3 class="timeline-title">${e.title}</h3>\n                        <p>${e.description}</p>\n                    </div>\n                </div>\n            `;t.insertAdjacentHTML("beforeend",a)});const n=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1});document.querySelectorAll(".timeline-event").forEach(e=>{n.observe(e)});const a=document.querySelectorAll(".node"),i=document.getElementById("diagram-info-title"),o=document.getElementById("diagram-info-desc"),r=document.getElementById("diagram-info-panel");a.forEach(e=>{const t=()=>{a.forEach(e=>e.classList.remove("active-node")),e.classList.add("active-node"),r.style.opacity=0,setTimeout(()=>{i.textContent=e.textContent,o.textContent=e.getAttribute("data-info"),r.style.opacity=1},300)};e.addEventListener("click",t),e.addEventListener("mouseenter",t),e.addEventListener("keydown",e=>{"Enter"!==e.key&&" "!==e.key||(e.preventDefault(),t())})});const s=[{url:"assets/Mahatma.png",caption:"Quit India Movement Mass Protests",source:"Representative Image"},{url:"https://picsum.photos/id/1025/600/400",caption:"Old Radio Transmitter Equipment",source:"Representative Image"},{url:"https://picsum.photos/id/1050/600/400",caption:"Bombay in the 1940s",source:"Representative Image"}],d=document.getElementById("gallery-grid");d&&s.forEach(e=>{const t=`\n                <div class="gallery-item">\n                    <div class="gallery-img-wrapper">\n                        <img src="${e.url}" alt="${e.caption}" class="gallery-img" loading="lazy">\n                    </div>\n                    <div class="gallery-caption">\n                        <strong>${e.caption}</strong>\n                        <span class="gallery-source">Source: ${e.source}</span>\n                    </div>\n                </div>\n            `;d.insertAdjacentHTML("beforeend",t)});const c=[{text:"Usha Mehta: Freedom Fighter Who Set Up A Secret Radio Station (Archive)",link:"#"},{text:"Quit India Movement: The role of Congress Radio",link:"#"},{text:"Padma Awards Directory (1954-2013)",link:"#"}],l=document.getElementById("references-list");l&&c.forEach(e=>{const t=`\n                <li>\n                    ${"#"!==e.link?`<a href="${e.link}" target="_blank" rel="noopener noreferrer">${e.text}</a>`:`<span>${e.text}</span>`}\n                </li>\n            `;l.insertAdjacentHTML("beforeend",t)})});